import{_ as r,a0 as a,w as p,s as l,ao as d,I as s,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop","title":"Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享","tag":"201408","desc":""},"relativePath":"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop.md","filePath":"[post].md"}'),u={name:"201408/20140804 Linux FAQs with Answers--How to enable and configure desktop sharing on Linux Mint Cinnamon desktop.md"};function m(x,n,g,f,C,L){const o=a("Link");return p(),l("div",null,[n[11]||(n[11]=d(`<h1 id="linux有問必答-如何在linux-mint-cinnamon啓用桌面共享" tabindex="-1">Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享 <a class="header-anchor" href="#linux有問必答-如何在linux-mint-cinnamon啓用桌面共享" aria-label="Permalink to “Linux有問必答：如何在Linux Mint Cinnamon啓用桌面共享”">​</a></h1><blockquote><p><strong>問題</strong>：我試着在Linux Mint 17 Cinnamon桌面上通過Vino VNC服務器（vino-server）啓用桌面共享。但是，我發現用來配置vino-server（如，共享選項，安全，通知開/關）的vino首選項工具已經不復存在了。同時，我也的Cinnamon桌面上也找不到共享菜單。我怎樣才能在最新的Linux Mint 17 Cinnamon桌面上通過vino-server配置桌面共享？</p></blockquote><p>最新的Linux Mint 17 Cinnamon桌面附帶了預安裝用於VNC桌面共享的vino-server，但是它報告説桌面共享菜單丟失了。</p><p>一個配置vino-server並啓用桌面共享的可選方式，是使用dconf-editor的圖形界面。</p><p>首先安裝dconf-editor：</p><pre><code>$ sudo apt-get install dconf-editor
</code></pre><p>啓動dconf-editor。</p><pre><code>$ dconf-editor
</code></pre><p>在dconf-editor的左邊面板中導航到“org-&gt;gnome-&gt;desktop-&gt;remote-access”，然後你將會看到各種各樣的桌面共享選項。</p><p><img src="https://farm4.staticflickr.com/3916/14843965473_e68598b01b_z.jpg" alt=""></p><p>最重要的是，點擊“enabled”來激活桌面遠程訪問。除此之外，你還可以自定義其它選項。</p><p>例如，你可以通過修改以下字段來啓用VNC密碼驗證：</p><ul><li><strong>authentication-methods</strong>: 設置為 [&#39;vnc&#39;]</li><li><strong>vnc-password</strong>: 將你喜歡的密碼修改為Base64編碼的字符串。</li></ul><p>在本例中，我們選擇“password”為VNC密碼，它的Base64編碼字符串為“cGFzc3dvcmQ=”。</p><p>你也可以選擇啓用其它選項：</p><ul><li>notify-on-connect: 當vino-server接收到連接請求時顯示桌面通知。</li><li>prompt-enabled: 遠程用户不允許通過VNC工具訪問桌面，除非VNC請求被該桌面的擁有者許可。</li></ul><h3 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to “排障”">​</a></h3><ol><li><p>當啓動vino-server時，我碰到了下面的錯誤。</p><p>** (vino-server:4280): WARNING **: The desktop sharing service is not enabled, so it should not be run.</p></li></ol><p>要啓用桌面共享服務，請使用上面講過的dconf-editor。 也可以選擇運行以下命令：</p><pre><code> # gsettings set org.gnome.Vino enabled true 
</code></pre><hr>`,21)),s("p",null,[n[1]||(n[1]=t("via: ",-1)),e(o,{href:"http://ask.xmodulo.com/enable-configure-desktop-sharing-linux-mint-cinnamon-desktop.html"},{default:i(()=>[...n[0]||(n[0]=[t("http://ask.xmodulo.com/enable-configure-desktop-sharing-linux-mint-cinnamon-desktop.html",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=t("譯者：",-1)),e(o,{href:"https://github.com/GOLinux"},{default:i(()=>[...n[2]||(n[2]=[t("GOLinux",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const v=r(u,[["render",m]]);export{k as __pageData,v as default};
